// Permanent articles are generated by the separate AI workflow in scripts/news_ai.py.
// This compatibility step intentionally performs no article creation: raw feed text must
// never be published as a substitute for an AI-written 4,000-character summary.
// Existing articles are preserved unchanged.
import fs from "node:fs";
import path from "node:path";
import {fileURLToPath} from "node:url";

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");
const file=path.join(ROOT,"data","articles.json");
if(!fs.existsSync(file)) throw new Error("data/articles.json is missing; refusing to create an empty replacement");
const data=JSON.parse(fs.readFileSync(file,"utf8"));
if(!data || typeof data!=="object" || !data.items || typeof data.items!=="object" || Array.isArray(data.items)) {
  throw new Error("data/articles.json has an unexpected schema; existing article data was not modified");
}
console.log("Non-AI article republishing is disabled. Preserved "+Object.keys(data.items).length+" existing articles; new permanent summaries are created only by scripts/news_ai.py.");
